cases.good:
for (const el of videoAncestorChain(player)) {
  el.style.setProperty('width', stageW + 'px', 'important');
  el.style.setProperty('height', stageH + 'px', 'important');
  const pos = getComputedStyle(el).position;
  if (pos === 'fixed' || pos === 'sticky') {
    el.style.setProperty('position', 'absolute', 'important');
  }
  el.style.setProperty('inset', '0', 'important');
}
// videoAncestorChain(player): querySelector('video') → parentElement walk tới player;
// fallback firstElementChild chain khi không có <video> (canvas players)
